mkdir -p /app/output && cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Reinvention at Global Scale</title>
  <meta name="description" content="Leap Studio is a global creative agency and reinvention partner for enterprise brands." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&family=Plus+Jakarta+Sans:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #0a0a0a;
      --surface: #121212;
      --surface-2: #171717;
      --text: #f6f6f6;
      --muted: #ababab;
      --line: #2a2a2a;
      --electric: #2b7fff;
      --amber: #ffb454;
      --radius: 16px;
      --shadow: 0 20px 60px rgba(0,0,0,.4);
      --max: 1240px;
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; background: var(--bg); color: var(--text); }
    body {
      font-family: "Plus Jakarta Sans", sans-serif;
      line-height: 1.5;
      overflow-x: hidden;
      background-image:
        radial-gradient(circle at 20% 10%, rgba(43,127,255,.12), transparent 45%),
        radial-gradient(circle at 80% 20%, rgba(255,180,84,.08), transparent 40%),
        linear-gradient(to bottom, rgba(255,255,255,.02), rgba(255,255,255,0));
    }

    h1, h2, h3, h4 { font-family: "Space Grotesk", sans-serif; margin: 0; letter-spacing: -.02em; }
    p { margin: 0; color: var(--muted); }
    a { color: inherit; text-decoration: none; }

    .container { width: min(var(--max), calc(100% - 2.5rem)); margin-inline: auto; }
    section { padding: 84px 0; }

    .nav {
      position: sticky;
      top: 0;
      z-index: 100;
      backdrop-filter: blur(12px);
      background: rgba(10, 10, 10, 0.72);
      border-bottom: 1px solid rgba(255,255,255,.08);
    }
    .nav-inner {
      height: 74px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }
    .brand {
      display: flex;
      align-items: center;
      gap: .7rem;
      font-family: "Space Grotesk", sans-serif;
      font-weight: 700;
      letter-spacing: .01em;
      font-size: 1.1rem;
    }
    .brand-badge {
      width: 28px;
      height: 28px;
      display: grid;
      place-items: center;
      border-radius: 8px;
      background: linear-gradient(135deg, var(--electric), #63a4ff);
      color: white;
      font-size: .85rem;
      font-weight: 700;
    }

    .menu {
      display: flex;
      align-items: center;
      gap: 1rem;
      font-size: .94rem;
    }
    .menu a {
      color: #e6e6e6;
      padding: .45rem .2rem;
      border-bottom: 1px solid transparent;
      transition: .25s ease;
    }
    .menu a:hover { color: white; border-bottom-color: var(--amber); }

    .lang-wrap { position: relative; }
    .lang-btn {
      background: var(--surface);
      border: 1px solid var(--line);
      color: var(--text);
      border-radius: 999px;
      padding: .55rem .85rem;
      cursor: pointer;
      font-family: inherit;
      display: flex;
      align-items: center;
      gap: .45rem;
    }
    .lang-menu {
      position: absolute;
      right: 0;
      top: calc(100% + .6rem);
      min-width: 190px;
      padding: .45rem;
      background: #111;
      border: 1px solid var(--line);
      border-radius: 12px;
      box-shadow: var(--shadow);
      display: none;
    }
    .lang-menu.open { display: block; }
    .lang-item {
      width: 100%;
      border: 0;
      background: transparent;
      color: var(--text);
      text-align: left;
      padding: .65rem .6rem;
      border-radius: 8px;
      cursor: pointer;
      font-family: inherit;
    }
    .lang-item:hover { background: rgba(255,255,255,.06); }

    .menu-toggle { display: none; }

    .hero {
      padding-top: 70px;
      padding-bottom: 60px;
    }
    .eyebrow {
      color: var(--amber);
      letter-spacing: .16em;
      font-size: .77rem;
      text-transform: uppercase;
      margin-bottom: 1rem;
    }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.15fr .85fr;
      gap: 2rem;
      align-items: end;
    }
    .hero h1 {
      font-size: clamp(2.3rem, 6vw, 5.3rem);
      line-height: .96;
      margin-bottom: 1.35rem;
      max-width: 12ch;
    }
    .hero p { max-width: 54ch; font-size: 1.05rem; }

    .hero-carousel {
      margin-top: 2rem;
      background: linear-gradient(160deg, #151515, #111);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      overflow: hidden;
      position: relative;
      min-height: 290px;
    }
    .hero-track { display: flex; transition: transform .6s cubic-bezier(.22,.61,.36,1); }
    .hero-card {
      min-width: 100%;
      padding: 1.5rem;
      display: grid;
      grid-template-columns: 1fr .95fr;
      gap: 1rem;
      align-items: stretch;
    }
    .hero-media {
      border-radius: 12px;
      min-height: 220px;
      background-size: cover;
      background-position: center;
      filter: saturate(.7) contrast(1.05) brightness(.86);
      position: relative;
      overflow: hidden;
    }
    .hero-media::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(10,10,10,.6), transparent 55%);
    }
    .hero-meta {
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 1rem;
      padding: .5rem 0;
    }
    .hero-tag {
      color: var(--electric);
      font-size: .8rem;
      text-transform: uppercase;
      letter-spacing: .12em;
    }
    .hero-meta h3 { font-size: clamp(1.3rem, 2.6vw, 2rem); line-height: 1.1; }

    .btn-row { display: flex; gap: .7rem; }
    .btn {
      border: 1px solid var(--line);
      color: var(--text);
      background: var(--surface);
      border-radius: 999px;
      padding: .55rem .95rem;
      font-family: inherit;
      cursor: pointer;
    }
    .btn-primary { background: linear-gradient(135deg, var(--electric), #4d98ff); border-color: transparent; }

    .controls {
      position: absolute;
      right: 1rem;
      bottom: 1rem;
      display: flex;
      gap: .5rem;
      z-index: 2;
    }

    .section-head { display: flex; justify-content: space-between; gap: 1rem; align-items: end; margin-bottom: 1.6rem; }
    .section-head h2 { font-size: clamp(1.7rem, 3.6vw, 2.8rem); }

    .region-tabs { display: flex; gap: .55rem; flex-wrap: wrap; margin-bottom: 1rem; }
    .region-tab {
      padding: .55rem .9rem;
      border-radius: 999px;
      background: var(--surface);
      border: 1px solid var(--line);
      color: var(--muted);
      cursor: pointer;
      font-family: inherit;
      transition: .25s;
    }
    .region-tab.active {
      background: rgba(43,127,255,.2);
      color: white;
      border-color: rgba(43,127,255,.6);
    }

    .team-wrap {
      position: relative;
      overflow: hidden;
      border-radius: var(--radius);
      border: 1px solid var(--line);
      background: linear-gradient(175deg, #121212, #0f0f0f);
      padding: 1rem;
    }
    .team-track {
      display: flex;
      gap: 1rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scroll-behavior: smooth;
      padding-bottom: .35rem;
    }
    .team-track::-webkit-scrollbar { height: 8px; }
    .team-track::-webkit-scrollbar-thumb { background: #333; border-radius: 999px; }

    .team-card {
      min-width: min(320px, 84vw);
      scroll-snap-align: start;
      border-radius: 14px;
      overflow: hidden;
      border: 1px solid #2b2b2b;
      background: #141414;
    }
    .team-photo {
      height: 220px;
      background-size: cover;
      background-position: center;
      filter: saturate(.75) brightness(.84);
    }
    .team-info { padding: 1rem; }
    .team-info h3 { font-size: 1.15rem; margin-bottom: .2rem; }
    .title { color: #d6d6d6; font-size: .95rem; margin-bottom: .55rem; }
    .quote { color: #c9c9c9; font-size: .94rem; margin-bottom: .8rem; }
    .office { color: var(--amber); font-size: .86rem; text-transform: uppercase; letter-spacing: .08em; }

    .scroller {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(280px, 360px);
      gap: 1rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      padding-bottom: .35rem;
    }
    .scroller::-webkit-scrollbar { height: 8px; }
    .scroller::-webkit-scrollbar-thumb { background: #343434; border-radius: 999px; }

    .card {
      scroll-snap-align: start;
      border-radius: 14px;
      border: 1px solid var(--line);
      background: var(--surface-2);
      overflow: hidden;
    }
    .thumb {
      height: 190px;
      background-size: cover;
      background-position: center;
      filter: saturate(.72) brightness(.82);
    }
    .card-body { padding: 1rem; }
    .card h3 { font-size: 1.2rem; margin-bottom: .45rem; }

    .cta-banner {
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: linear-gradient(130deg, rgba(43,127,255,.18), rgba(255,180,84,.12));
      padding: 2rem;
      display: grid;
      gap: 1rem;
      align-items: center;
      grid-template-columns: 1fr auto;
    }

    .grid-2 { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 1rem; }
    .grid-3 { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 1rem; }
    .grid-4 { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 1rem; }

    .panel {
      border: 1px solid var(--line);
      border-radius: 14px;
      padding: 1rem;
      background: #121212;
    }

    footer {
      border-top: 1px solid var(--line);
      padding: 2rem 0 3rem;
      color: #bbb;
      font-size: .92rem;
    }

    .cookie {
      position: fixed;
      left: 1rem;
      right: 1rem;
      bottom: 1rem;
      z-index: 120;
      background: #101010;
      border: 1px solid var(--line);
      border-radius: 14px;
      padding: 1rem;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: .8rem;
      box-shadow: var(--shadow);
    }
    .cookie-actions { display: flex; gap: .55rem; flex-wrap: wrap; }

    @media (max-width: 1020px) {
      .menu {
        position: fixed;
        inset: 74px 0 auto 0;
        background: rgba(10,10,10,.98);
        border-bottom: 1px solid var(--line);
        padding: .8rem 1.2rem 1rem;
        flex-direction: column;
        align-items: flex-start;
        transform: translateY(-120%);
        transition: .3s;
      }
      .menu.open { transform: translateY(0); }
      .menu-toggle {
        display: inline-flex;
        border: 1px solid var(--line);
        background: var(--surface);
        color: var(--text);
        border-radius: 10px;
        padding: .45rem .7rem;
      }
      .hero-grid { grid-template-columns: 1fr; }
      .hero-card { grid-template-columns: 1fr; }
      .grid-4 { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .grid-3 { grid-template-columns: 1fr 1fr; }
      .cta-banner { grid-template-columns: 1fr; }
      .cookie { grid-template-columns: 1fr; }
    }
    @media (max-width: 700px) {
      section { padding: 68px 0; }
      .container { width: min(var(--max), calc(100% - 1.4rem)); }
      .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
      .hero { padding-top: 50px; }
      .hero h1 { font-size: clamp(2rem, 13vw, 3.2rem); }
    }
  </style>
</head>
<body>
  <header class="nav">
    <div class="container nav-inner">
      <div class="brand">
        <span class="brand-badge">L</span>
        <span>Leap Studio</span>
      </div>

      <nav id="mainMenu" class="menu" aria-label="Primary navigation">
        <a href="#insights">Insights</a>
        <a href="#work">Work</a>
        <a href="#how">Services</a>
        <a href="#principles">Culture</a>
        <a href="#cta">Make Your Mark</a>
        <a href="#footer">Contact Us</a>
      </nav>

      <div style="display:flex; align-items:center; gap:.65rem;">
        <div class="lang-wrap">
          <button id="langBtn" class="lang-btn" aria-haspopup="true" aria-expanded="false">Global EN ▾</button>
          <div id="langMenu" class="lang-menu" role="menu" aria-label="Language selector">
            <button class="lang-item" role="menuitem">Global EN</button>
            <button class="lang-item" role="menuitem">France FR</button>
            <button class="lang-item" role="menuitem">China CN</button>
          </div>
        </div>
        <button id="menuToggle" class="menu-toggle" aria-label="Toggle menu">☰</button>
      </div>
    </div>
  </header>

  <main>
    <section class="hero container" id="top">
      <div class="eyebrow">Global Creative Reinvention Partner</div>
      <div class="hero-grid">
        <div>
          <h1>We design leaps that enterprises can feel.</h1>
          <p>Leap Studio blends strategic imagination, product rigor, and cinematic storytelling to reinvent customer experience for global organizations. We partner with brand leaders and innovation teams to move from complexity to clarity.</p>
        </div>
        <div class="panel">
          <p style="margin-bottom:.55rem; color:#dedede;">Global studios across New York, San Francisco, London, Munich, Singapore, and Melbourne.</p>
          <p>From AI transformation to next-gen retail systems, we scale breakthroughs across markets and cultures.</p>
        </div>
      </div>

      <div class="hero-carousel" aria-label="Featured content carousel">
        <div id="heroTrack" class="hero-track"></div>
        <div class="controls">
          <button id="heroPrev" class="btn" aria-label="Previous slide">←</button>
          <button id="heroNext" class="btn" aria-label="Next slide">→</button>
        </div>
      </div>
    </section>

    <section id="team" class="container">
      <div class="section-head">
        <div>
          <div class="eyebrow">Global Studios</div>
          <h2>Meet the people behind the leap</h2>
        </div>
      </div>

      <div id="regionTabs" class="region-tabs" role="tablist" aria-label="Team regions"></div>
      <div class="team-wrap">
        <div id="teamTrack" class="team-track" aria-live="polite"></div>
      </div>
    </section>

    <section id="work" class="container">
      <div class="section-head">
        <div>
          <div class="eyebrow">Client Work</div>
          <h2>Category-defining outcomes</h2>
        </div>
      </div>
      <div id="workScroller" class="scroller" aria-label="Work showcase carousel"></div>
    </section>

    <section id="cta" class="container">
      <div class="cta-banner">
        <div>
          <h2 style="font-size:clamp(1.6rem, 3vw, 2.4rem); margin-bottom:.5rem;">Ready to redefine what your brand can do?</h2>
          <p>Partner with Leap Studio to turn strategic ambition into experiences customers remember.</p>
        </div>
        <div class="btn-row">
          <button class="btn btn-primary">Start a Conversation</button>
          <button class="btn">Explore Capabilities</button>
        </div>
      </div>
    </section>

    <section id="how" class="container">
      <div class="section-head">
        <div>
          <div class="eyebrow">How We Work</div>
          <h2>Built for velocity, depth, and scale</h2>
        </div>
      </div>
      <div class="grid-3">
        <article class="panel"><h3>Discover</h3><p>We map customer realities, business constraints, and future opportunities through fast research sprints.</p></article>
        <article class="panel"><h3>Design</h3><p>Cross-functional teams prototype services, products, and narratives that fuse art and systems thinking.</p></article>
        <article class="panel"><h3>Deploy</h3><p>We operationalize change with enterprise-ready roadmaps, capability transfer, and measurable impact.</p></article>
      </div>
    </section>

    <section id="insights" class="container">
      <div class="section-head">
        <div>
          <div class="eyebrow">Latest Insights</div>
          <h2>What’s shaping tomorrow now</h2>
        </div>
      </div>
      <div id="insightsGrid" class="grid-3"></div>
    </section>

    <section id="principles" class="container">
      <div class="section-head">
        <div>
          <div class="eyebrow">Our Principles</div>
          <h2>How we create lasting momentum</h2>
        </div>
      </div>
      <div id="principlesGrid" class="grid-4"></div>
    </section>
  </main>

  <footer id="footer">
    <div class="container" style="display:flex; justify-content:space-between; flex-wrap:wrap; gap:1rem;">
      <div>© 2026 Leap Studio. Reinvention at global scale.</div>
      <div>New York · San Francisco · London · Munich · Singapore · Melbourne</div>
    </div>
  </footer>

  <div id="cookieBanner" class="cookie" role="dialog" aria-label="Cookie consent">
    <p>We use cookies to improve performance, personalize content, and understand usage patterns across global markets.</p>
    <div class="cookie-actions">
      <button class="btn btn-primary" data-cookie="accept">Accept all</button>
      <button class="btn" data-cookie="manage">Manage settings</button>
      <button class="btn" data-cookie="decline">Decline all</button>
    </div>
  </div>

  <script>
    const heroItems = [
      {
        type: "Insight Report",
        title: "When Human Connection Meets AI",
        desc: "A field guide for designing emotionally intelligent enterprise experiences.",
        image: "https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&w=1400&q=80"
      },
      {
        type: "Project Highlight",
        title: "Modernizing the Point-of-Sale Experience",
        desc: "Reframing retail operations into intuitive, connected journeys.",
        image: "https://images.unsplash.com/photo-1556740749-887f6717d7e4?auto=format&fit=crop&w=1400&q=80"
      },
      {
        type: "Podcast Episode",
        title: "From Complexity to Clarity",
        desc: "Leaders discuss how enterprise teams align data, creativity, and impact.",
        image: "https://images.unsplash.com/photo-1475721027785-f74eccf877e2?auto=format&fit=crop&w=1400&q=80"
      }
    ];

    const teamByRegion = {
      "North America": [
        { name: "Ariana Brooks", title: "Managing Director, Strategy", quote: "Enterprise reinvention starts when we design for belief, not just behavior.", office: "New York", photo: "https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?auto=format&fit=crop&w=900&q=80" },
        { name: "Luis Carter", title: "Executive Creative Lead", quote: "We build signature experiences that scale from flagship to everyday touchpoints.", office: "San Francisco", photo: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=900&q=80" },
        { name: "Mina Patel", title: "Director, Experience Systems", quote: "The strongest brands architect consistency without sacrificing surprise.", office: "New York", photo: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=900&q=80" }
      ],
      "Asia": [
        { name: "Jun Wei Tan", title: "Head of Innovation Programs", quote: "Speed matters, but strategic clarity is what sustains transformation.", office: "Singapore", photo: "https://images.unsplash.com/photo-1504593811423-6dd665756598?auto=format&fit=crop&w=900&q=80" },
        { name: "Priya Menon", title: "Principal Service Designer", quote: "We translate complex ecosystems into services people actually trust.", office: "Singapore", photo: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?auto=format&fit=crop&w=900&q=80" }
      ],
      "Europe": [
        { name: "Sophie Laurent", title: "Partner, Brand Transformation", quote: "Luxury and technology are not opposites—they're multipliers when orchestrated well.", office: "London", photo: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=900&q=80" },
        { name: "Lukas Reinhardt", title: "Data Experience Director", quote: "Data is only powerful when made legible to decision-makers in motion.", office: "Munich", photo: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=900&q=80" }
      ],
      "Oceania": [
        { name: "Amelia Ross", title: "Studio Lead, Culture & Change", quote: "The future is built by teams brave enough to redesign their own operating model.", office: "Melbourne", photo: "https://images.unsplash.com/photo-1488426862026-3ee34a7d66df?auto=format&fit=crop&w=900&q=80" },
        { name: "Noah Hall", title: "Creative Technology Director", quote: "We prototype tomorrow in weeks, then make it enterprise-grade.", office: "Melbourne", photo: "https://images.unsplash.com/photo-1463453091185-61582044d556?auto=format&fit=crop&w=900&q=80" }
      ]
    };

    const workProjects = [
      "Creating Consumer Insights at Scale",
      "Deepening Customer Engagement",
      "Harnessing Data for Leaner and Greener Future of Mobility",
      "Modernizing the Point-of-Sale Experience",
      "Reimagining Luxury Craftsmanship",
      "Helping Healthier Habits Stick"
    ];

    const insights = [
      "When Human Connection Meets AI",
      "Writing the Future of AI",
      "Amplifying Clinical Care with AI",
      "The Future of Customer Experience",
      "Next-Gen Contact Centers: Powered by AI",
      "From Complexity to Clarity"
    ];

    const principles = [
      "Challenge the status quo",
      "Fuse art & science to make ideas real",
      "Create a lasting impact at global scale",
      "Regenerate systems & communities"
    ];

    const heroTrack = document.getElementById('heroTrack');
    const heroPrev = document.getElementById('heroPrev');
    const heroNext = document.getElementById('heroNext');
    let heroIndex = 0;

    heroTrack.innerHTML = heroItems.map(item => `
      <article class="hero-card">
        <div class="hero-media" style="background-image:url('${item.image}')"></div>
        <div class="hero-meta">
          <div>
            <div class="hero-tag">${item.type}</div>
            <h3>${item.title}</h3>
            <p style="margin-top:.65rem;">${item.desc}</p>
          </div>
          <div class="btn-row"><button class="btn btn-primary">Explore</button><button class="btn">Listen / Read</button></div>
        </div>
      </article>
    `).join('');

    function renderHero() {
      heroTrack.style.transform = `translateX(-${heroIndex * 100}%)`;
    }
    heroPrev.addEventListener('click', () => { heroIndex = (heroIndex - 1 + heroItems.length) % heroItems.length; renderHero(); });
    heroNext.addEventListener('click', () => { heroIndex = (heroIndex + 1) % heroItems.length; renderHero(); });
    setInterval(() => { heroIndex = (heroIndex + 1) % heroItems.length; renderHero(); }, 6000);

    const regionTabs = document.getElementById('regionTabs');
    const teamTrack = document.getElementById('teamTrack');
    const regions = ["North America", "Asia", "Europe", "Oceania"];
    let activeRegion = regions[0];

    function renderTabs() {
      regionTabs.innerHTML = regions.map(region => `
